//! A radial menu with press-drag selection and keyboard access.
use crate::{
    foundation::{Theme, ThemeMode},
    primitives::{
        direct_touch::Contact,
        family::{PhaseClock, Slide, disabled_motion, ease, measure},
        flyout::TriggerBounds,
        glyph::{Glyph, drawing, icon},
        presentation::{row, tr},
    },
};
use gpui::{prelude::*, *};
use std::time::Duration;

const TRIGGER: f32 = 56.;
const BUTTON: f32 = 46.;
const DEFAULT_RADIUS: f32 = 104.;
const DEAD_ZONE: f32 = 34.;
const REACH_MARGIN: f32 = 60.;
const TAP_LIMIT: f32 = 0.34;
const DONE_DURATION: Duration = Duration::from_millis(1400);

/// An action mark. SVG assets use the current foreground ink.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum OrbitIcon {
    Glyph(Glyph),
    Album,
    Share,
    Svg(SharedString),
}

impl From<Glyph> for OrbitIcon {
    fn from(value: Glyph) -> Self {
        Self::Glyph(value)
    }
}

/// The semantic tone of an action.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum OrbitTone {
    #[default]
    Neutral,
    Danger,
}

/// One action with a stable ID, visible label and optional confirmation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OrbitAction {
    pub id: SharedString,
    pub label: SharedString,
    pub icon: OrbitIcon,
    pub done: Option<SharedString>,
    pub tone: OrbitTone,
}

impl OrbitAction {
    pub fn new(
        id: impl Into<SharedString>,
        label: impl Into<SharedString>,
        icon: impl Into<OrbitIcon>,
    ) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            icon: icon.into(),
            done: None,
            tone: OrbitTone::Neutral,
        }
    }

    pub fn with_done(mut self, label: impl Into<SharedString>) -> Self {
        self.done = Some(label.into());
        self
    }

    pub fn with_tone(mut self, tone: OrbitTone) -> Self {
        self.tone = tone;
        self
    }
}

/// Identifies the selected action. The host performs its effect.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OrbitInvoked(pub SharedString);

/// Reports the change in the arc's interactive state.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OrbitOpenChanged(pub bool);

struct Slot {
    action: OrbitAction,
    focus: FocusHandle,
    reveal: Slide,
    emphasis: Slide,
    magnet_x: Slide,
    magnet_y: Slide,
    drawn: (f32, f32, f32),
}

impl Slot {
    fn new(action: OrbitAction, cx: &mut Context<OrbitMenu>) -> Self {
        Self {
            action,
            focus: cx.focus_handle().tab_stop(true),
            reveal: Slide::new(0.),
            emphasis: Slide::new(0.),
            magnet_x: Slide::new(0.),
            magnet_y: Slide::new(0.),
            drawn: (0., 0., 0.),
        }
    }
}

#[derive(Clone, Copy)]
struct Press {
    was_open: bool,
    clock: PhaseClock,
    origin: Point<Pixels>,
    moved: bool,
    touch: bool,
}

/// A circular trigger that opens a short arc of actions.
pub struct OrbitMenu {
    id: SharedString,
    slots: Vec<Slot>,
    label: Option<SharedString>,
    radius: f32,
    spread: f32,
    direction: f32,
    disabled: bool,
    announce: bool,
    open: bool,
    press: Option<Press>,
    pointer: Option<Point<Pixels>>,
    target: Option<usize>,
    roving: Option<usize>,
    bounds: TriggerBounds,
    contact: Contact,
    focus_group: FocusHandle,
    trigger: FocusHandle,
    _focus_out: Subscription,
    _window_activation: Subscription,
    done: Option<SharedString>,
    done_timer: Option<Task<()>>,
    arc: Slide,
    scale: Slide,
    lens_x: Slide,
    lens_y: Slide,
    lens_alpha: Slide,
    lens_seeded: bool,
    glyph: Glyph,
    previous_glyph: Glyph,
    glyph_clock: PhaseClock,
    pill_text: SharedString,
    pill_before: SharedString,
    pill_clock: PhaseClock,
    pill_width: Option<Slide>,
    pill_alpha: Slide,
}

impl EventEmitter<OrbitInvoked> for OrbitMenu {}
impl EventEmitter<OrbitOpenChanged> for OrbitMenu {}

impl OrbitMenu {
    pub fn new(actions: Vec<OrbitAction>, w: &mut Window, cx: &mut Context<Self>) -> Self {
        let focus_group = cx.focus_handle();
        let trigger = cx.focus_handle().tab_stop(true);
        let focus_out = cx.on_focus_out(&focus_group, w, |s: &mut Self, _, _, cx| s.close(cx));
        let activation = cx.observe_window_activation(w, |s: &mut Self, w, cx| {
            if !w.is_window_active() {
                s.close(cx);
            }
        });
        Self {
            id: format!("orbit-menu-{}", cx.entity_id()).into(),
            slots: actions.into_iter().map(|a| Slot::new(a, cx)).collect(),
            label: None,
            radius: DEFAULT_RADIUS,
            spread: 150.,
            direction: -90.,
            disabled: false,
            announce: true,
            open: false,
            press: None,
            pointer: None,
            target: None,
            roving: None,
            bounds: TriggerBounds::default(),
            contact: Contact::default(),
            focus_group,
            trigger,
            _focus_out: focus_out,
            _window_activation: activation,
            done: None,
            done_timer: None,
            arc: Slide::new(0.),
            scale: Slide::new(1.),
            lens_x: Slide::new(0.),
            lens_y: Slide::new(0.),
            lens_alpha: Slide::new(0.),
            lens_seeded: false,
            glyph: Glyph::More,
            previous_glyph: Glyph::More,
            glyph_clock: PhaseClock::default(),
            pill_text: "".into(),
            pill_before: "".into(),
            pill_clock: PhaseClock::default(),
            pill_width: None,
            pill_alpha: Slide::new(0.),
        }
    }

    pub fn with_id(mut self, id: impl Into<SharedString>) -> Self {
        self.id = id.into();
        self
    }

    pub fn with_label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = Some(label.into());
        self
    }

    pub fn with_radius(mut self, radius: f32) -> Self {
        if radius.is_finite() {
            self.radius = radius.max(1.);
        }
        self
    }

    pub fn with_spread(mut self, degrees: f32) -> Self {
        if degrees.is_finite() {
            self.spread = degrees.clamp(0., 360.);
        }
        self
    }

    pub fn with_direction(mut self, degrees: f32) -> Self {
        if degrees.is_finite() {
            self.direction = degrees.rem_euclid(360.);
        }
        self
    }

    pub fn with_disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    pub fn with_announce(mut self, announce: bool) -> Self {
        self.announce = announce;
        self
    }

    /// Replace actions, retaining focus and animation by action ID.
    pub fn set_actions(&mut self, actions: Vec<OrbitAction>, cx: &mut Context<Self>) {
        let targeted = self.target.map(|i| self.slots[i].action.id.clone());
        let focused = self.roving.map(|i| self.slots[i].action.id.clone());
        let mut old = std::mem::take(&mut self.slots);
        self.slots = actions
            .into_iter()
            .map(|action| {
                if let Some(index) = old.iter().position(|s| s.action.id == action.id) {
                    let mut slot = old.remove(index);
                    slot.action = action;
                    slot
                } else {
                    let mut slot = Slot::new(action, cx);
                    if self.open {
                        slot.reveal.duration(1., 0.42, cx);
                    }
                    slot
                }
            })
            .collect();
        self.target = targeted.and_then(|id| self.slots.iter().position(|s| s.action.id == id));
        self.roving = focused.and_then(|id| self.slots.iter().position(|s| s.action.id == id));
        if self.slots.is_empty() {
            self.close(cx);
        }
        cx.notify();
    }

    pub fn set_disabled(&mut self, disabled: bool, cx: &mut Context<Self>) {
        if self.disabled != disabled {
            self.disabled = disabled;
            if disabled {
                self.close(cx);
            }
            cx.notify();
        }
    }

    pub fn is_open(&self) -> bool {
        self.open
    }

    /// Restore keyboard focus to the trigger after a host action.
    pub fn focus_trigger(&self, w: &mut Window, cx: &mut Context<Self>) {
        self.trigger.focus(w, cx);
    }

    /// Clear the confirmation and close the menu without firing an action.
    pub fn reset(&mut self, cx: &mut Context<Self>) {
        self.done_timer = None;
        self.done = None;
        self.close(cx);
        self.change_glyph(Glyph::More, cx);
        cx.notify();
    }

    fn enabled(&self) -> bool {
        !self.disabled && !self.slots.is_empty()
    }

    fn change_glyph(&mut self, glyph: Glyph, cx: &App) {
        if self.glyph != glyph {
            self.previous_glyph = self.glyph;
            self.glyph = glyph;
            self.glyph_clock.restart(cx);
        }
    }

    fn set_open(&mut self, open: bool, cx: &mut Context<Self>) {
        if self.open == open {
            return;
        }
        self.open = open;
        let count = self.slots.len();
        for (i, slot) in self.slots.iter_mut().enumerate() {
            let stagger = if open {
                i as f32 * 0.022
            } else {
                (count - 1 - i) as f32 * 0.016
            };
            slot.reveal
                .delayed(f32::from(open), if open { 0.42 } else { 0.24 }, stagger, cx);
        }
        self.arc
            .duration(f32::from(open), if open { 0.38 } else { 0.20 }, cx);
        self.scale.duration(if open { 0.94 } else { 1. }, 0.26, cx);
        self.change_glyph(if open { Glyph::Close } else { Glyph::More }, cx);
        cx.emit(OrbitOpenChanged(open));
        cx.notify();
    }

    fn close(&mut self, cx: &mut Context<Self>) {
        self.press = None;
        self.pointer = None;
        self.target = None;
        self.roving = None;
        self.set_open(false, cx);
    }

    fn open(&mut self, cx: &mut Context<Self>) {
        if !self.enabled() {
            return;
        }
        self.done_timer = None;
        self.done = None;
        self.set_open(true, cx);
    }

    fn fire(&mut self, i: usize, w: &mut Window, cx: &mut Context<Self>) {
        if !self.open || !self.enabled() {
            return;
        }
        let action = self.slots[i].action.clone();
        self.close(cx);
        self.done = Some(action.done.unwrap_or(action.label));
        self.change_glyph(Glyph::Check, cx);
        self.trigger.focus(w, cx);
        cx.emit(OrbitInvoked(action.id));
        self.done_timer = Some(cx.spawn(async move |view, cx| {
            cx.background_executor().timer(DONE_DURATION).await;
            let _ = view.update(cx, |s, cx| {
                s.done = None;
                s.change_glyph(Glyph::More, cx);
                cx.notify();
            });
        }));
        cx.notify();
    }

    fn begin(&mut self, point: Point<Pixels>, touch: bool, w: &mut Window, cx: &mut Context<Self>) {
        if !self.enabled() || self.press.is_some() || !self.hit_trigger(point) {
            return;
        }
        let was_open = self.open;
        let mut clock = PhaseClock::default();
        clock.restart(cx);
        self.press = Some(Press {
            was_open,
            origin: point,
            touch,
            moved: false,
            clock,
        });
        self.roving = None;
        self.target = None;
        self.pointer = None;
        self.trigger.focus(w, cx);
        self.open(cx);
        cx.notify();
    }

    fn moved(&mut self, point: Point<Pixels>, touch: bool, cx: &mut Context<Self>) {
        let Some(mut press) = self.press.filter(|p| p.touch == touch) else {
            return;
        };
        let delta = point - press.origin;
        press.moved |= f32::from(delta.x).hypot(f32::from(delta.y)) > 5.;
        self.press = Some(press);
        self.pointer = (!touch).then_some(point);
        self.target = press.moved.then(|| self.pick(point)).flatten();
        cx.notify();
    }

    fn release(
        &mut self,
        point: Point<Pixels>,
        touch: bool,
        cancelled: bool,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(press) = self.press.filter(|p| p.touch == touch) else {
            return;
        };
        if cancelled {
            self.close(cx);
            return;
        }
        self.moved(point, touch, cx);
        let press = self.press.take().unwrap_or(press);
        if press.moved
            && let Some(i) = self.target
        {
            self.fire(i, w, cx);
        } else if press.moved || press.was_open || press.clock.age(cx) >= TAP_LIMIT {
            self.close(cx);
        } else {
            self.target = None;
            self.pointer = None;
            cx.notify();
        }
    }

    fn pick(&self, point: Point<Pixels>) -> Option<usize> {
        let delta = point - self.bounds.get().center();
        let (x, y) = (f32::from(delta.x), f32::from(delta.y));
        let distance = x.hypot(y);
        if self.slots.is_empty() || !(DEAD_ZONE..=self.radius + REACH_MARGIN).contains(&distance) {
            return None;
        }
        let angle = y.atan2(x).to_degrees();
        let offset = angle_delta(angle, self.direction);
        let step = self.spread / self.slots.len().saturating_sub(1).max(1) as f32;
        let tolerance = (step / 2.).clamp(12., 18.);
        if offset.abs() > self.spread / 2. + tolerance {
            return None;
        }
        (0..self.slots.len()).min_by(|&a, &b| {
            angle_delta(
                angle,
                action_angle(a, self.slots.len(), self.direction, self.spread),
            )
            .abs()
            .total_cmp(
                &angle_delta(
                    angle,
                    action_angle(b, self.slots.len(), self.direction, self.spread),
                )
                .abs(),
            )
        })
    }

    fn direct_hit(&self, point: Point<Pixels>) -> Option<usize> {
        let delta = point - self.bounds.get().center();
        let (x, y) = (f32::from(delta.x), f32::from(delta.y));
        self.slots.iter().position(|s| {
            let (cx, cy, side) = s.drawn;
            side > 0. && (cx - x).hypot(cy - y) <= side / 2.
        })
    }

    fn hit_trigger(&self, point: Point<Pixels>) -> bool {
        let delta = point - self.bounds.get().center();
        f32::from(delta.x).hypot(f32::from(delta.y)) <= TRIGGER / 2.
    }

    fn focus_action(&mut self, index: usize, w: &mut Window, cx: &mut Context<Self>) {
        self.open(cx);
        if !self.open {
            return;
        }
        self.press = None;
        self.pointer = None;
        self.roving = Some(index);
        self.target = Some(index);
        self.slots[index].focus.focus(w, cx);
        cx.notify();
    }

    fn trigger_key(&mut self, event: &KeyDownEvent, w: &mut Window, cx: &mut Context<Self>) {
        if !self.enabled() {
            return;
        }
        let i = match event.keystroke.key.as_str() {
            "up" => self.slots.len() - 1,
            "down" | "right" | "left" => 0,
            "enter" | "space" if !event.is_held => {
                if self.open {
                    self.close(cx);
                } else {
                    self.focus_action(0, w, cx);
                }
                w.prevent_default();
                cx.stop_propagation();
                return;
            }
            "tab" if self.open => {
                self.advance_tab(event.keystroke.modifiers.shift, w, cx);
                w.prevent_default();
                cx.stop_propagation();
                return;
            }
            "escape" if self.open => {
                self.close(cx);
                self.trigger.focus(w, cx);
                cx.stop_propagation();
                return;
            }
            _ => return,
        };
        self.focus_action(i, w, cx);
        w.prevent_default();
        cx.stop_propagation();
    }

    fn action_key(
        &mut self,
        i: usize,
        event: &KeyDownEvent,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.open {
            return;
        }
        let n = self.slots.len();
        let target = match event.keystroke.key.as_str() {
            "up" | "left" => Some((i + n - 1) % n),
            "down" | "right" => Some((i + 1) % n),
            "home" => Some(0),
            "end" => Some(n - 1),
            "enter" | "space" if !event.is_held => {
                self.fire(i, w, cx);
                None
            }
            "escape" => {
                self.close(cx);
                self.trigger.focus(w, cx);
                None
            }
            "tab" => {
                self.advance_tab(event.keystroke.modifiers.shift, w, cx);
                None
            }
            _ => return,
        };
        if let Some(index) = target {
            self.focus_action(index, w, cx);
        }
        w.prevent_default();
        cx.stop_propagation();
    }

    fn advance_tab(&mut self, back: bool, w: &mut Window, cx: &mut Context<Self>) {
        self.close(cx);
        self.trigger.focus(w, cx);
        w.on_next_frame(move |w, cx| {
            if back {
                w.focus_prev(cx);
            } else {
                w.focus_next(cx);
            }
        });
    }
}

fn angle_delta(a: f32, b: f32) -> f32 {
    (a - b + 180.).rem_euclid(360.) - 180.
}

fn action_angle(i: usize, n: usize, direction: f32, spread: f32) -> f32 {
    if n <= 1 {
        direction
    } else {
        direction + spread * (i as f32 / (n - 1) as f32 - 0.5)
    }
}

fn offset(radius: f32, angle: f32) -> (f32, f32) {
    let (s, c) = angle.to_radians().sin_cos();
    (c * radius, s * radius)
}

struct Material {
    text: Hsla,
    inverse: Hsla,
    solid: Hsla,
    glass: Hsla,
    action: Hsla,
    line: Hsla,
    track: Hsla,
    danger: Hsla,
    shadow: Vec<BoxShadow>,
}

impl Material {
    fn get(cx: &App) -> Self {
        let dark = Theme::global(cx).mode == ThemeMode::Dark;
        let (text, inverse, surface, line, track, danger) = if dark {
            (0xf2f2f2, 0x141414, 0x1f1f1f, 0x484848, 0x484848, 0xf0738f)
        } else {
            (0x0b0b0b, 0xffffff, 0xffffff, 0xd6d6d6, 0xc4c4c4, 0xbb2c54)
        };
        let shadow = if dark {
            vec![shadow(0.22, 8., 22.)]
        } else {
            vec![shadow(0.065, 6., 18.), shadow(0.035, 1., 3.)]
        };
        Self {
            text: rgb(text).into(),
            inverse: rgb(inverse).into(),
            solid: rgb(text).into(),
            glass: rgb(surface).opacity(0.76).into(),
            action: rgb(surface).opacity(0.94).into(),
            line: rgb(line).opacity(0.55).into(),
            track: rgb(track).into(),
            danger: rgb(danger).into(),
            shadow,
        }
    }
}

fn shadow(alpha: f32, y: f32, blur: f32) -> BoxShadow {
    BoxShadow {
        color: black().opacity(alpha),
        offset: point(px(0.), px(y)),
        blur_radius: px(blur),
        spread_radius: px(0.),
        inset: false,
    }
}

fn action_mark(value: OrbitIcon, size: f32, ink: Hsla) -> AnyElement {
    match value {
        OrbitIcon::Glyph(glyph) => icon(glyph, size, ink).into_any_element(),
        OrbitIcon::Svg(path) => svg()
            .path(path)
            .size(px(size))
            .flex_none()
            .text_color(ink)
            .into_any_element(),
        OrbitIcon::Album | OrbitIcon::Share => canvas(
            |_, _, _| (),
            move |b, _, w, _| {
                let at = |x, y| b.origin + point(px(x * size / 24.), px(y * size / 24.));
                let mut p = PathBuilder::stroke(px(size * 1.75 / 24.));
                if value == OrbitIcon::Album {
                    p.move_to(at(3., 6.));
                    p.curve_to(at(5., 4.), at(3., 4.));
                    p.line_to(at(9., 4.));
                    p.line_to(at(12., 7.));
                    p.line_to(at(19., 7.));
                    p.curve_to(at(21., 9.), at(21., 7.));
                    p.line_to(at(21., 18.));
                    p.curve_to(at(19., 20.), at(21., 20.));
                    p.line_to(at(5., 20.));
                    p.curve_to(at(3., 18.), at(3., 20.));
                    p.close();
                    p.move_to(at(12., 10.));
                    p.line_to(at(12., 17.));
                    p.move_to(at(8.5, 13.5));
                    p.line_to(at(15.5, 13.5));
                } else {
                    p.move_to(at(8., 10.5));
                    p.line_to(at(15.3, 6.3));
                    p.move_to(at(8., 13.5));
                    p.line_to(at(15.3, 17.7));
                    for (x, y) in [(5., 12.), (18., 5.), (18., 19.)] {
                        let r = point(px(size / 8.), px(size / 8.));
                        p.move_to(at(x + 3., y));
                        p.arc_to(r, px(0.), false, true, at(x - 3., y));
                        p.arc_to(r, px(0.), false, true, at(x + 3., y));
                        p.close();
                    }
                }
                if let Ok(path) = p.build() {
                    w.paint_path(path, ink);
                }
            },
        )
        .size(px(size))
        .flex_none()
        .into_any_element(),
    }
}

impl Render for OrbitMenu {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let m = Material::get(cx);
        let reduced = disabled_motion(cx);
        let label = self
            .label
            .clone()
            .unwrap_or_else(|| tr(cx, "Actions", "操作").into());
        let arc = self.arc.get(w, cx).clamp(0., 1.);
        let size = TRIGGER * self.scale.get(w, cx);
        let radius = self.radius;
        let direction = self.direction;
        let spread = self.spread;
        let count = self.slots.len();
        let moving = self.open || arc > 0.001;
        let pointer = self
            .pointer
            .filter(|_| self.open && !reduced)
            .map(|point| point - self.bounds.get().center());
        let frames: Vec<_> = self
            .slots
            .iter_mut()
            .enumerate()
            .map(|(i, slot)| {
                let p = slot.reveal.get(w, cx).clamp(0., 1.);
                let angle = action_angle(i, count, direction, spread);
                let (x, y) = offset(
                    radius * p,
                    angle + if reduced { 0. } else { 44. * (1. - p) },
                );
                let (mx, my) = pointer.map_or((0., 0.), |point| {
                    let (dx, dy) = (f32::from(point.x) - x, f32::from(point.y) - y);
                    let pull = 0.16 * (1. - dx.hypot(dy) / 78.).clamp(0., 1.);
                    (dx * pull, dy * pull)
                });
                slot.magnet_x.duration(mx, 0.19, cx);
                slot.magnet_y.duration(my, 0.19, cx);
                let x = x + slot.magnet_x.get(w, cx);
                let y = y + slot.magnet_y.get(w, cx);
                slot.emphasis
                    .duration(f32::from(self.open && self.target == Some(i)), 0.26, cx);
                let high = slot.emphasis.get(w, cx).clamp(0., 1.);
                let side = BUTTON * (0.4 + p * 0.6) * (1. + high * 0.10);
                slot.drawn = (x, y, side * f32::from(self.open && p > 0.48));
                (x, y, side, p, high)
            })
            .collect();
        let highlighted = self
            .target
            .filter(|_| self.open)
            .and_then(|i| frames.get(i).map(|frame| (i, *frame)));
        if let Some((_, (x, y, _, _, _))) = highlighted {
            if !self.lens_seeded {
                self.lens_x.reset(x);
                self.lens_y.reset(y);
                self.lens_seeded = true;
            }
            self.lens_x.duration(x, 0.24, cx);
            self.lens_y.duration(y, 0.24, cx);
        }
        self.lens_alpha
            .duration(f32::from(highlighted.is_some()), 0.22, cx);
        let lens_alpha = self.lens_alpha.get(w, cx).clamp(0., 1.);
        if lens_alpha < 0.001 && highlighted.is_none() {
            self.lens_seeded = false;
        }
        let lens_at = (self.lens_x.get(w, cx), self.lens_y.get(w, cx));
        let lens_side = highlighted
            .map_or(BUTTON * 1.1, |(_, (_, _, side, _, _))| side.max(BUTTON))
            * (0.86 + 0.14 * lens_alpha);
        let lens_ink =
            if highlighted.is_some_and(|(i, _)| self.slots[i].action.tone == OrbitTone::Danger) {
                m.solid.blend(m.danger.opacity(0.14))
            } else {
                m.solid
            };

        let mut root = div()
            .id(self.id.clone())
            .relative()
            .size(px(TRIGGER))
            .flex_none()
            .track_focus(&self.focus_group)
            .tab_stop(false)
            .child(self.bounds.measure());
        if moving {
            let line = m.track.opacity(arc * 0.88);
            root = root.child(
                canvas(
                    |_, _, _| (),
                    move |b, _, w, _| {
                        let mut path = PathBuilder::stroke(px(1.5));
                        for i in 0..=32 {
                            let a = direction + spread * (i as f32 / 32. - 0.5) * arc;
                            let (x, y) = offset(radius * arc, a);
                            let p = b.center() + point(px(x), px(y));
                            if i == 0 {
                                path.move_to(p);
                            } else {
                                path.line_to(p);
                            }
                        }
                        if let Ok(path) = path.build() {
                            w.paint_path(path, line);
                        }
                    },
                )
                .absolute()
                .inset_0(),
            );
        }
        if lens_alpha > 0.001 {
            root = root.child(
                div()
                    .id("orbit-lens")
                    .debug_selector(|| "orbit-lens".into())
                    .absolute()
                    .left(px(TRIGGER / 2. + lens_at.0 - lens_side / 2.))
                    .top(px(TRIGGER / 2. + lens_at.1 - lens_side / 2.))
                    .size(px(lens_side))
                    .rounded_full()
                    .bg(lens_ink)
                    .shadow(m.shadow.clone())
                    .opacity(lens_alpha),
            );
        }
        if moving {
            let mut menu = div()
                .id("orbit-actions")
                .when(self.open, |menu| {
                    menu.role(Role::Menu).aria_label(label.clone())
                })
                .absolute()
                .inset_0();
            for (i, ((x, y, side, p, high), slot)) in
                frames.into_iter().zip(&self.slots).enumerate()
            {
                let fore = if high >= 0.52 {
                    m.inverse
                } else if slot.action.tone == OrbitTone::Danger {
                    m.danger
                } else {
                    m.text
                };
                let mut item = row()
                    .id(slot.action.id.clone())
                    .debug_selector({
                        let name = slot.action.label.clone();
                        move || name.to_string()
                    })
                    .absolute()
                    .left(px(TRIGGER / 2. + x - side / 2.))
                    .top(px(TRIGGER / 2. + y - side / 2.))
                    .size(px(side))
                    .justify_center()
                    .rounded_full()
                    .opacity(p)
                    .when(high < 0.99, |b| {
                        b.bg(m.action.opacity(1. - high))
                            .border_1()
                            .border_color(m.line.opacity(1. - high))
                            .shadow(m.shadow.clone())
                    })
                    .child(action_mark(
                        slot.action.icon.clone(),
                        18. * side / BUTTON,
                        fore,
                    ));
                if self.open {
                    item =
                        item.role(Role::MenuItem)
                            .aria_label(slot.action.label.clone())
                            .track_focus(&slot.focus)
                            .tab_stop(self.roving == Some(i) || (self.roving.is_none() && i == 0))
                            .block_mouse_except_scroll()
                            .cursor_pointer()
                            .on_click(cx.listener(move |s, e: &ClickEvent, w, cx| {
                                if e.is_keyboard() || s.direct_hit(e.position()) == Some(i) {
                                    s.fire(i, w, cx);
                                }
                            }))
                            .on_key_down(cx.listener(move |s, e: &KeyDownEvent, w, cx| {
                                s.action_key(i, e, w, cx)
                            }));
                }
                menu = menu.child(item);
            }
            root = root.child(menu);
        }
        let trigger_fore = if self.open { m.text } else { m.inverse };
        let glyph_t = ease(self.glyph_clock.time(0.18, w, cx) / 0.18);
        let trigger = row()
            .id("orbit-trigger")
            .debug_selector(|| "orbit-trigger".into())
            .relative()
            .size(px(TRIGGER))
            .justify_center()
            .rounded_full()
            .role(Role::Button)
            .aria_label(label.clone())
            .aria_expanded(self.open)
            .track_focus(&self.trigger)
            .tab_stop(self.enabled())
            .block_mouse_except_scroll()
            .focus_visible(move |s| {
                s.shadow(vec![BoxShadow {
                    color: m.track,
                    offset: point(px(0.), px(0.)),
                    blur_radius: px(0.),
                    spread_radius: px(2.),
                    inset: false,
                }])
            })
            .child(
                row()
                    .size(px(size))
                    .rounded_full()
                    .justify_center()
                    .bg(if self.open { m.glass } else { m.solid })
                    .when(self.open, |b| b.border_1().border_color(m.line))
                    .shadow(m.shadow.clone())
                    .opacity(if self.enabled() { 1. } else { 0.42 })
                    .child(drawing(
                        self.previous_glyph,
                        self.glyph,
                        glyph_t,
                        24. * size / TRIGGER,
                        trigger_fore,
                        false,
                    )),
            )
            .when(self.enabled(), |trigger| {
                trigger
                    .cursor_pointer()
                    .on_mouse_down(
                        MouseButton::Left,
                        cx.listener(|s, e: &MouseDownEvent, w, cx| {
                            s.begin(e.position, false, w, cx)
                        }),
                    )
                    .on_click(cx.listener(|s, e: &ClickEvent, w, cx| {
                        if e.is_keyboard() {
                            if s.open {
                                s.close(cx);
                                s.trigger.focus(w, cx);
                            } else {
                                s.focus_action(0, w, cx);
                            }
                        }
                    }))
                    .on_key_down(cx.listener(Self::trigger_key))
                    .child(self.contact.listen(cx, |s, e, w, cx| match e.phase {
                        TouchPhase::Started => s.begin(e.start_position, true, w, cx),
                        TouchPhase::Moved => s.moved(e.position, true, cx),
                        TouchPhase::Ended => s.release(e.position, true, false, w, cx),
                        TouchPhase::Cancelled => s.release(e.position, true, true, w, cx),
                    }))
            });
        root = root.child(trigger);
        let text = if let Some(i) = self.target.filter(|_| self.open) {
            Some(self.slots[i].action.label.clone())
        } else if self.open {
            Some(if self.press.is_some_and(|p| p.moved) {
                tr(cx, "Release to cancel", "松手取消").into()
            } else {
                label
            })
        } else {
            self.done.clone()
        };
        self.pill_alpha
            .duration(f32::from(text.is_some()), 0.22, cx);
        if let Some(text) = text.filter(|t| *t != self.pill_text) {
            self.pill_before = std::mem::replace(&mut self.pill_text, text);
            self.pill_clock.restart(cx);
        }
        let pill_alpha = self.pill_alpha.get(w, cx).clamp(0., 1.);
        if pill_alpha > 0.001 {
            let width = (measure(&self.pill_text, 14., w).ceil() + 28.).max(46.);
            let width_slide = self.pill_width.get_or_insert(Slide::new(width));
            width_slide.duration(width, 0.31, cx);
            let width = width_slide.get(w, cx);
            let swap = ease(self.pill_clock.time(0.16, w, cx) / 0.16);
            let (x, y) = offset(radius * 0.5, direction);
            root = root.child(
                row()
                    .id("orbit-pill")
                    .debug_selector(|| "orbit-pill".into())
                    .absolute()
                    .left(px(TRIGGER / 2. + x - width / 2.))
                    .top(px(TRIGGER / 2. + y - 16. + (1. - pill_alpha) * 6.))
                    .w(px(width))
                    .h(px(32.))
                    .overflow_hidden()
                    .justify_center()
                    .rounded_full()
                    .border_1()
                    .border_color(m.line)
                    .bg(m.glass)
                    .shadow(m.shadow.clone())
                    .opacity(pill_alpha)
                    .text_color(m.text)
                    .text_size(px(14.))
                    .font_weight(FontWeight::MEDIUM)
                    .when(!self.pill_before.is_empty() && swap < 0.999, |b| {
                        b.child(
                            row()
                                .absolute()
                                .inset_0()
                                .justify_center()
                                .top(px(-4. * swap))
                                .whitespace_nowrap()
                                .opacity(1. - swap)
                                .child(self.pill_before.clone()),
                        )
                    })
                    .child(
                        div()
                            .relative()
                            .top(px(4. * (1. - swap)))
                            .whitespace_nowrap()
                            .opacity(swap)
                            .child(self.pill_text.clone()),
                    ),
            );
        } else if !self.open && self.done.is_none() {
            self.pill_width = None;
            self.pill_text = "".into();
            self.pill_before = "".into();
        }
        if self.announce
            && let Some(done) = &self.done
        {
            root = root.child(
                div()
                    .id("orbit-status")
                    .role(Role::Status)
                    .aria_label(done.clone())
                    .absolute()
                    .size(px(0.)),
            );
        }
        let mouse_move = cx.listener(|s, e: &MouseMoveEvent, _, cx| {
            if s.press.is_some() && e.pressed_button == Some(MouseButton::Left) {
                s.moved(e.position, false, cx);
            } else if s.open && s.press.is_none() && e.pressed_button.is_none() {
                let relative = e.position - s.bounds.get().center();
                let near =
                    f32::from(relative.x).hypot(f32::from(relative.y)) <= s.radius + REACH_MARGIN;
                let pointer = near.then_some(e.position);
                let target = s.direct_hit(e.position).or(s.roving);
                if s.pointer != pointer || s.target != target {
                    s.pointer = pointer;
                    s.target = target;
                    cx.notify();
                }
            }
        });
        let mouse_up = cx.listener(|s, e: &MouseUpEvent, w, cx| {
            if e.button == MouseButton::Left {
                s.release(e.position, false, false, w, cx);
            }
        });
        let outside = cx.listener(|s, e: &MouseDownEvent, _, cx| {
            if s.open
                && s.press.is_none()
                && !s.hit_trigger(e.position)
                && s.direct_hit(e.position).is_none()
            {
                s.close(cx);
            }
        });
        root.child(
            canvas(
                |_, _, _| (),
                move |_, _, w, _| {
                    w.on_mouse_event(move |e: &MouseMoveEvent, phase, w, cx| {
                        if phase.capture() {
                            mouse_move(e, w, cx);
                        }
                    });
                    w.on_mouse_event(move |e: &MouseUpEvent, phase, w, cx| {
                        if phase.capture() {
                            mouse_up(e, w, cx);
                        }
                    });
                    w.on_mouse_event(move |e: &MouseDownEvent, phase, w, cx| {
                        if phase.capture() {
                            outside(e, w, cx);
                        }
                    });
                },
            )
            .absolute()
            .size(px(0.)),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::{OrbitAction, OrbitInvoked, OrbitMenu, OrbitOpenChanged};
    use crate::primitives::glyph::Glyph;
    use gpui::{
        Context, Entity, FocusHandle, IntoElement, Modifiers, MouseButton, Render, TestAppContext,
        TouchEvent, TouchId, TouchPhase, VisualTestContext, Window, div, point, prelude::*, px,
    };
    use std::{cell::RefCell, rc::Rc, time::Duration};

    struct Harness {
        menu: Entity<OrbitMenu>,
        next: FocusHandle,
    }

    impl Harness {
        fn new(w: &mut Window, cx: &mut Context<Self>) -> Self {
            let menu = cx.new(|cx| {
                OrbitMenu::new(
                    vec![
                        OrbitAction::new("like", "Like", Glyph::Heart).with_done("Liked"),
                        OrbitAction::new("pin", "Pin", Glyph::Pin),
                        OrbitAction::new("save", "Save", Glyph::Save),
                        OrbitAction::new("get", "Download", Glyph::Download),
                        OrbitAction::new("delete", "Delete", Glyph::Trash),
                    ],
                    w,
                    cx,
                )
            });
            Self {
                menu,
                next: cx.focus_handle().tab_stop(true),
            }
        }
    }

    impl Render for Harness {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            div()
                .relative()
                .size(px(400.))
                .child(
                    div()
                        .absolute()
                        .left(px(165.))
                        .top(px(210.))
                        .child(self.menu.clone()),
                )
                .child(
                    div()
                        .id("after-orbit")
                        .track_focus(&self.next)
                        .tab_stop(true)
                        .absolute()
                        .left(px(16.))
                        .top(px(300.))
                        .size(px(32.)),
                )
        }
    }

    fn tick(w: &mut VisualTestContext, ms: u64) {
        w.executor().advance_clock(Duration::from_millis(ms));
        w.run_until_parked();
        w.update(|w, cx| {
            w.simulate_next_frame(cx);
            w.refresh();
        });
        w.run_until_parked();
    }

    #[test]
    fn a_short_tap_pins_the_menu_and_a_stationary_hold_closes_it() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(Harness::new);
        let menu = w.update(|_, cx| view.read(cx).menu.clone());
        let center = w.debug_bounds("orbit-trigger").unwrap().center();
        let opens = Rc::new(RefCell::new(Vec::new()));
        let _sub = w.update(|_, cx| {
            let opens = opens.clone();
            cx.subscribe(&menu, move |_, event: &OrbitOpenChanged, _| {
                opens.borrow_mut().push(event.0)
            })
        });
        w.simulate_mouse_down(center, MouseButton::Left, Modifiers::default());
        assert!(w.update(|_, cx| menu.read(cx).is_open()));
        tick(w, 339);
        w.simulate_mouse_up(center, MouseButton::Left, Modifiers::default());
        assert!(w.update(|_, cx| menu.read(cx).is_open()));
        w.simulate_click(center, Modifiers::default());
        assert!(!w.update(|_, cx| menu.read(cx).is_open()));
        w.simulate_mouse_down(center, MouseButton::Left, Modifiers::default());
        tick(w, 340);
        w.simulate_mouse_up(center, MouseButton::Left, Modifiers::default());
        assert!(!w.update(|_, cx| menu.read(cx).is_open()));
        assert_eq!(opens.borrow().as_slice(), &[true, false, true, false]);
    }

    #[test]
    fn angular_drag_fires_once_with_a_timed_confirmation_and_off_arc_cancels() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(Harness::new);
        let menu = w.update(|_, cx| view.read(cx).menu.clone());
        let center = w.debug_bounds("orbit-trigger").unwrap().center();
        let actions = Rc::new(RefCell::new(Vec::new()));
        let _sub = w.update(|_, cx| {
            let actions = actions.clone();
            cx.subscribe(&menu, move |_, event: &OrbitInvoked, _| {
                actions.borrow_mut().push(event.0.clone())
            })
        });
        for delta in [
            point(px(0.), px(72.)),
            point(px(-179.), px(-48.)),
            point(px(-22.), px(-6.)),
        ] {
            w.simulate_mouse_down(center, MouseButton::Left, Modifiers::default());
            w.simulate_mouse_move(
                center + delta,
                Some(MouseButton::Left),
                Modifiers::default(),
            );
            w.simulate_mouse_up(center + delta, MouseButton::Left, Modifiers::default());
            assert!(!w.update(|_, cx| menu.read(cx).is_open()));
        }
        assert!(actions.borrow().is_empty());
        let inside = center + point(px(-62.), px(-17.));
        w.simulate_mouse_down(center, MouseButton::Left, Modifiers::default());
        w.simulate_mouse_move(inside, Some(MouseButton::Left), Modifiers::default());
        w.simulate_mouse_up(inside, MouseButton::Left, Modifiers::default());
        w.run_until_parked();
        assert_eq!(actions.borrow().as_slice(), &["like"]);
        tick(w, 1399);
        w.update(|w, cx| {
            let s = menu.read(cx);
            assert_eq!(s.done.as_deref(), Some("Liked"));
            assert!(s.trigger.is_focused(w));
        });
        tick(w, 1);
        assert!(w.update(|_, cx| menu.read(cx).done.is_none()));
    }

    #[test]
    fn keyboard_wraps_and_tab_advances_outside_the_arc() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(Harness::new);
        let menu = w.update(|_, cx| view.read(cx).menu.clone());
        w.update(|w, cx| menu.update(cx, |s, cx| s.focus_trigger(w, cx)));
        w.simulate_keystrokes("up");
        w.update(|w, cx| assert!(menu.read(cx).slots[4].focus.is_focused(w)));
        w.simulate_keystrokes("right");
        w.update(|w, cx| assert!(menu.read(cx).slots[0].focus.is_focused(w)));
        w.simulate_keystrokes("escape");
        w.update(|w, cx| assert!(menu.read(cx).trigger.is_focused(w)));
        w.simulate_keystrokes("enter");
        w.update(|w, cx| assert!(menu.read(cx).slots[0].focus.is_focused(w)));
        w.simulate_keystrokes("tab");
        tick(w, 20);
        w.update(|w, cx| {
            assert!(!menu.read(cx).is_open());
            assert!(view.read(cx).next.is_focused(w));
        });
    }

    #[test]
    fn cancelled_touch_dismisses_and_a_rotated_arc_uses_the_same_dead_zone() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(Harness::new);
        let menu = w.update(|_, cx| view.read(cx).menu.clone());
        let center = w.debug_bounds("orbit-trigger").unwrap().center();
        let toward = center + point(px(0.), px(-65.));
        for (phase, position) in [
            (TouchPhase::Started, center),
            (TouchPhase::Moved, toward),
            (TouchPhase::Cancelled, toward),
        ] {
            w.simulate_event(TouchEvent {
                id: TouchId(1),
                phase,
                position,
                ..Default::default()
            });
            tick(w, 16);
        }
        w.update(|_, cx| {
            menu.update(cx, |s, _| {
                assert!(!s.is_open());
                assert!(s.done.is_none());
                s.direction = 90.;
                assert_eq!(s.pick(center + point(px(0.), px(75.))), Some(2));
                assert_eq!(s.pick(center + point(px(0.), px(33.))), None);
                assert_eq!(s.pick(toward), None);
            })
        });
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Direct contact input for controls that cannot wait for a synthesized tap.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};
#[derive(Default, Clone)]
pub(crate) struct Contact(Rc<Cell<bool>>);
impl Contact {
    /// Mount over the gesture target. Only the topmost, hovered hitbox may claim a new contact.
    pub(crate) fn listen<T: 'static>(
        &self,
        cx: &Context<T>,
        handle: impl Fn(&mut T, &TouchDragEvent, &mut Window, &mut Context<T>) + 'static,
    ) -> impl IntoElement {
        let listener = cx.listener(handle);
        let active = self.0.clone();
        canvas(
            |bounds, w, _| w.insert_hitbox(bounds, HitboxBehavior::Normal),
            move |_, hit, w, _| {
                w.on_mouse_event(move |e: &TouchDragEvent, phase, w, cx| {
                    if phase.bubble() {
                        if e.phase == TouchPhase::Started {
                            active.set(hit.is_hovered(w));
                        }
                        if !active.get() {
                            return;
                        }
                        if matches!(e.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                            active.set(false)
                        }
                        if e.phase == TouchPhase::Started {
                            w.prevent_default();
                        }
                        listener(e, w, cx);
                        cx.stop_propagation();
                    }
                })
            },
        )
        .absolute()
        .inset_0()
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Window-relative placement for transient surfaces.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Default, Clone)]
pub(crate) struct TriggerBounds(Rc<Cell<Bounds<Pixels>>>);
impl TriggerBounds {
    pub fn measure(&self) -> impl IntoElement {
        let saved = self.0.clone();
        canvas(move |b, _, _| saved.set(b), |_, _, _, _| ())
            .absolute()
            .inset_0()
    }
    pub fn get(&self) -> Bounds<Pixels> {
        self.0.get()
    }
    /// Prefer below the trigger. Flip above when it leaves more room.
    pub fn place(
        &self,
        view: Size<Pixels>,
        height: Pixels,
        gap: Pixels,
    ) -> (Point<Pixels>, Anchor) {
        let b = self.get();
        if b.bottom() + gap + height > view.height - px(10.) && b.top() > view.height - b.bottom() {
            (point(b.left(), b.top() - gap), Anchor::BottomLeft)
        } else {
            (point(b.left(), b.bottom() + gap), Anchor::TopLeft)
        }
    }
}

